+</style>
+</head>
+<body>
+
+<div id="source-badge">loading&#8230;</div>
+
+<div class="container">
+
+  <header class="header anim-in">
+    <div class="header-inner">
+      <div>
+        <div class="wordmark">T-24</div>
+        <div class="tagline">Prove whether you&#8217;re affected before the CRA clock runs out.</div>
+      </div>
+      <div class="header-meta">
+        <div class="header-product" id="hdr-product">&#8212;</div>
+        <div class="header-detail" id="hdr-scanned">&#8212;</div>
+        <div class="triage-pill" id="hdr-triage">&#8212;</div>
+      </div>
+    </div>
+  </header>
+
+  <section class="cra-panel">
+    <div class="section-title">CRA ENISA Deadline Clock</div>
+    <div id="cra-content"></div>
+  </section>
+
+  <section>
+    <div class="section-title">Scan Summary</div>
+    <div class="summary-strip" id="summary-strip"></div>
+  </section>
+
+  <section>
+    <div class="section-title">Findings</div>
+    <div class="findings-list" id="findings-list"></div>
+  </section>
+
+  <section>
+    <div class="section-title">Downloads</div>
+    <div class="downloads-section" id="downloads-section">
+      <span class="downloads-label">Downloads</span>
+    </div>
+  </section>
+
+  <footer class="footer">
+    <div class="footer-note" id="footer-note">
+      <strong>Verdicts are decided by deterministic code analysis.</strong>
+      The AI only reads advisories &#8212; it never sets a VEX status.
+      Every evidence path cites a real source file and line number.
+    </div>
+    <div class="footer-brand">T-24 / IBM Bob 2.0 Hackathon</div>
+  </footer>
+
+</div>
+
+<script>
+(function () {
+  "use strict";
+
+  var EMBEDDED = {"product":"demo_product","scanned_at":"2026-09-26T18:52:29Z","duration_s":4.7,"summary":{"advisories":4,"affected":1,"not_affected":2,"under_investigation":1,"emergency_releases_avoided":2},"clock":{"cve":"CVE-2020-14343","aware_at":"2026-09-26T15:53:29Z","early_warning_due":"2026-09-27T15:53:29Z","notification_due":"2026-09-29T15:53:29Z","final_report_due":"2026-10-10T15:53:29Z"},"findings":[{"cve":"CVE-2020-14343","package":"PyYAML","installed":"5.3.1","affected_range":"<5.4","fixed_version":"5.4","symbols":["full_load"],"status":"affected","justification":null,"evidence":[{"file":"demo_product/app.py","line":14,"function":"upload_config","call":"config.load_settings"},{"file":"demo_product/config.py","line":5,"function":"load_settings","call":"yaml.full_load"}],"reason":"yaml.full_load is reachable from route /upload-config via upload_config -> load_settings","advisory_source":"https://github.com/advisories/GHSA-8q59-q68h-6hv4","drafts":["out/drafts/early_warning_CVE-2020-14343.md","out/drafts/notification_CVE-2020-14343.md"]},{"cve":"CVE-2023-50447","package":"Pillow","installed":"9.5.0","affected_range":"<10.2.0","fixed_version":"10.2.0","symbols":["PIL.ImageMath.eval"],"status":"not_affected","justification":"vulnerable_code_not_in_execute_path","evidence":[],"reason":"No path from any entry point reaches PIL.ImageMath.eval","advisory_source":"https://github.com/advisories/GHSA-3f63-hfp8-52jq","drafts":[]},{"cve":"CVE-2024-22195","package":"Jinja2","installed":"3.1.2","affected_range":"<3.1.3","fixed_version":"3.1.3","symbols":["xmlattr"],"status":"not_affected","justification":"vulnerable_code_not_in_execute_path","evidence":[],"reason":"No path from any entry point reaches xmlattr","advisory_source":"https://github.com/advisories/GHSA-h5c8-rqwp-cp95","drafts":[]},{"cve":"CVE-2023-32681","package":"requests","installed":"2.30.0","affected_range":">=2.3.0,<2.31.0","fixed_version":"2.31.0","symbols":[],"status":"under_investigation","justification":null,"evidence":[],"reason":"Leak requires proxies configured at runtime; static analysis cannot prove absence","advisory_source":"https://github.com/advisories/GHSA-j8r2-6x86-q33q","drafts":[]}],"coverage":{"files_found":3,"files_parsed":3},"vex_path":"out/vex.json"};
+
+  function loadData() {
+    var badge = document.getElementById('source-badge');
+    // Try live out/dossier.json
+    return fetch('../out/dossier.json', {cache:'no-cache'})
+      .then(function(r){ if(!r.ok) throw new Error(); return r.json(); })
+      .then(function(d){ badge.textContent='● live: out/dossier.json'; badge.className='live'; return d; })
+      .catch(function(){
+        // Try sample
+        return fetch('./sample_dossier.json', {cache:'no-cache'})
+          .then(function(r){ if(!r.ok) throw new Error(); return r.json(); })
+          .then(function(d){ badge.textContent='● demo: sample_dossier.json'; badge.className='demo'; return d; })
+          .catch(function(){
+            badge.textContent='● embedded fallback'; badge.className='embed';
+            return Promise.resolve(EMBEDDED);
+          });
+      });
+  }
+
+  function esc(s) {
+    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
+  }
+
+  function fmtDate(iso) {
+    try {
+      return new Date(iso).toLocaleString('en-GB',{
+        year:'numeric',month:'short',day:'numeric',
+        hour:'2-digit',minute:'2-digit',timeZoneName:'short',timeZone:'UTC'
+      });
+    } catch(e){ return iso; }
+  }
+
+  function fmtDuration(s) {
+    return s < 60 ? s.toFixed(1)+'s' : (s/60).toFixed(1)+'m';
+  }
+
+  function renderHeader(d) {
+    document.getElementById('hdr-product').textContent = d.product;
+    document.getElementById('hdr-scanned').textContent = fmtDate(d.scanned_at);
+    document.getElementById('hdr-triage').textContent =
+      'Triaged '+d.summary.advisories+' advisories in '+fmtDuration(d.duration_s);
+    document.title = 'T-24 \u2014 '+d.product;
+  }
+
+  var CIRCUMFERENCE = 2 * Math.PI * 38;
+
+  var TIMER_DEFS = [
+    { key:'early_warning_due', label:'Early Warning',  article:'CRA Art.\u00a014\u00a0\u00a71', totalH:24 },
+    { key:'notification_due',  label:'Notification',   article:'CRA Art.\u00a014\u00a0\u00a72', totalH:72 },
+    { key:'final_report_due',  label:'Final Report',   article:'CRA Art.\u00a014\u00a0\u00a73', totalH:14*24 }
+  ];
+
+  function timerState(secLeft, totalSec) {
+    var pct = Math.max(0, secLeft / totalSec);
+    if (secLeft <= 0)  return {cls:'overdue', color:'var(--red)',   pct:0};
+    if (pct <= 0.15)   return {cls:'danger',  color:'var(--red)',   pct:pct};
+    if (pct <= 0.35)   return {cls:'amber',   color:'var(--amber)', pct:pct};
+    return                    {cls:'calm',    color:'var(--green)', pct:pct};
+  }
+
+  function fmtCountdown(sec) {
+    if (sec <= 0) return 'OVERDUE';
+    var d = Math.floor(sec/86400);
+    var h = Math.floor((sec%86400)/3600);
+    var m = Math.floor((sec%3600)/60);
+    var s = sec%60;
+    function pad(n){ return n<10?'0'+n:String(n); }
+    if (d > 0) return d+'d '+pad(h)+'h '+pad(m)+'m';
+    return pad(h)+':'+pad(m)+':'+pad(s);
+  }
+
+  var timerIntervals = [];
+
+  function renderClock(clock) {
+    var el = document.getElementById('cra-content');
+    if (!clock) {
+      el.innerHTML = '<div class="no-clock-panel"><div class="no-clock-icon">\u2713</div>'
+        +'<div class="no-clock-text"><strong>No actively exploited finding. No ENISA report due.</strong>'
+        +'Pass <code>--actively-exploited CVE-XXXX-XXXXX=&lt;ISO8601&gt;</code> to activate the CRA clock.</div></div>';
+      return;
+    }
+
+    var metaHtml = '<div style="font-size:12px;color:var(--muted);margin-bottom:12px;">'
+      +'CVE: <strong style="color:var(--text);font-family:var(--font-mono)">'+esc(clock.cve)+'</strong>'
+      +' &nbsp;|&nbsp; Aware at: <span style="font-family:var(--font-mono)">'+fmtDate(clock.aware_at)+'</span></div>';
+    el.innerHTML = metaHtml + '<div class="cra-timers" id="cra-timers-grid"></div>';
+
+    var grid = document.getElementById('cra-timers-grid');
+
+    TIMER_DEFS.forEach(function(t, i) {
+      var dueMs  = new Date(clock[t.key]).getTime();
+      var totalSec = t.totalH * 3600;
+      var id = 'timer-'+i;
+
+      var card = document.createElement('div');
+      card.className = 'timer-card';
+      card.id = id;
+      card.innerHTML = '<div class="timer-label">'+esc(t.label)+'</div>'
+        +'<div class="ring-wrap"><svg viewBox="0 0 88 88">'
+        +'<circle class="ring-bg" cx="44" cy="44" r="38"/>'
+        +'<circle class="ring-fg" id="'+id+'-ring" cx="44" cy="44" r="38"'
+        +' stroke-dasharray="'+CIRCUMFERENCE+'" stroke-dashoffset="'+CIRCUMFERENCE+'" stroke="var(--green)"/>'
+        +'</svg><div class="ring-text"><span class="hh" id="'+id+'-pct">\u2026</span><span>left</span></div></div>'
+        +'<div class="timer-countdown" id="'+id+'-cd">\u2026</div>'
+        +'<div class="timer-due">Due: '+fmtDate(clock[t.key])+'</div>'
+        +'<div class="timer-article">'+esc(t.article)+'</div>';
+      grid.appendChild(card);
+
+      function tick() {
+        var now = Date.now();
+        var secLeft = Math.max(0, Math.floor((dueMs - now) / 1000));
+        var st = timerState(secLeft, totalSec);
+        card.className = 'timer-card '+st.cls;
+        var ring = document.getElementById(id+'-ring');
+        ring.style.stroke = st.color;
+        ring.style.strokeDashoffset = CIRCUMFERENCE * (1 - st.pct);
+        document.getElementById(id+'-pct').textContent = Math.round(st.pct*100)+'%';
+        var cdEl = document.getElementById(id+'-cd');
+        if (secLeft <= 0) {
+          cdEl.className = 'timer-countdown overdue-text';
+          cdEl.textContent = 'OVERDUE';
+        } else {
+          cdEl.className = 'timer-countdown';
+          cdEl.textContent = fmtCountdown(secLeft);
+        }
+      }
+      tick();
+      timerIntervals.push(setInterval(tick, 1000));
+    });
+  }
+
+  function renderSummary(s) {
+    var el = document.getElementById('summary-strip');
+    var items = [
+      {v:s.advisories,           l:'Advisories',          hero:false},
+      {v:s.affected,             l:'Affected',             hero:false},
+      {v:s.not_affected,         l:'Not Affected',         hero:false},
+      {v:s.under_investigation,  l:'Under Investigation',  hero:false},
+      {v:s.emergency_releases_avoided, l:'Emergency Releases\u00a0Avoided', hero:true}
+    ];
+    el.innerHTML = items.map(function(item){
+      return '<div class="stat-card'+(item.hero?' hero':'')+'"><div class="stat-value">'+item.v+'</div>'
+             +'<div class="stat-label">'+esc(item.l)+'</div></div>';
+    }).join('');
+  }
+
+  function renderEvidence(evidence, symbols, status) {
+    if (!evidence || evidence.length === 0) {
+      if (status === 'not_affected' && symbols && symbols.length > 0) {
+        return '<div class="evidence-block"><div class="evidence-title">Evidence Path</div>'
+          +'<div class="no-evidence-note">No path from any entry point reaches '
+          +'<code>'+symbols.map(esc).join(', ')+'</code>.</div></div>';
+      }
+      return '';
+    }
+    var hops = evidence.map(function(hop, i){
+      var isLast = i === evidence.length - 1;
+      var connector = isLast ? '' : '<div class="hop-connector"></div>';
+      return '<div class="hop" data-hop="'+i+'">'
+        +'<div class="hop-line"><div class="hop-dot'+(isLast?' last':'')+'"></div>'+connector+'</div>'
+        +'<div class="hop-content">'
+        +'<div class="hop-file">'+esc(hop.file)+':'+hop.line+'</div>'
+        +'<div class="hop-func">'+esc(hop.function)+'</div>'
+        +'<div class="hop-call">'+esc(hop.call)+'</div>'
+        +'</div></div>';
+    }).join('');
+    return '<div class="evidence-block"><div class="evidence-title">Evidence Path \u2014 '
+      +evidence.length+' hop'+(evidence.length!==1?'s':'')+'</div>'
+      +'<div class="evidence-chain">'+hops+'</div></div>';
+  }
+
+  function renderFinding(f, idx) {
+    var statusLabels = {
+      affected:'Affected', not_affected:'Not Affected',
+      under_investigation:'Under Investigation', fixed:'Fixed'
+    };
+    var statusLabel = statusLabels[f.status] || f.status;
+
+    var symbolsHtml = (f.symbols && f.symbols.length > 0)
+      ? '<div class="symbols-row"><span class="symbol-key">Symbols:</span>'
+        + f.symbols.map(function(s){ return '<span class="symbol-chip">'+esc(s)+'</span>'; }).join('')
+        + '</div>'
+      : '';
+
+    var justHtml = f.justification
+      ? '<div><span class="justification-pill">'+esc(f.justification)+'</span></div>'
+      : '';
+
+    var evHtml = renderEvidence(f.evidence, f.symbols, f.status);
+
+    var draftsHtml = (f.drafts && f.drafts.length > 0)
+      ? '<div class="drafts-row"><span>Draft reports:</span>'
+        + f.drafts.map(function(p){
+            var name = p.split('/').pop();
+            return '<a class="draft-link" href="../'+esc(p)+'">'+esc(name)+'</a>';
+          }).join('') + '</div>'
+      : '';
+
+    return '<div class="finding-card status-'+esc(f.status)+'" style="transition-delay:'+idx*80+'ms">'
+      +'<div class="finding-header"><div>'
+      +'<div class="finding-cve">'+esc(f.cve)+'</div>'
+      +'<div class="finding-pkg"><strong>'+esc(f.package)+'</strong></div>'
+      +'</div><div class="finding-header-right">'
+      +'<span class="badge '+esc(f.status)+'"><span class="badge-dot"></span>'+statusLabel+'</span>'
+      +'</div></div>'
+      +'<div class="finding-body">'
+      +'<div class="version-row">'
+      +'<div class="version-item"><span class="version-key">Installed</span><span class="version-val bad">'+esc(f.installed)+'</span></div>'
+      +'<div class="version-item"><span class="version-key">Affected Range</span><span class="version-val">'+esc(f.affected_range)+'</span></div>'
+      +'<div class="version-item"><span class="version-key">Fixed In</span><span class="version-val good">'+esc(f.fixed_version)+'</span></div>'
+      +'</div>'
+      +symbolsHtml
+      +'<div class="reason-row">'+esc(f.reason)+'</div>'
+      +justHtml+evHtml+draftsHtml
+      +'<div class="advisory-link">Advisory: <a href="'+esc(f.advisory_source)+'" target="_blank" rel="noopener">'+esc(f.advisory_source)+'</a></div>'
+      +'</div></div>';
+  }
+
+  function renderFindings(findings) {
+    document.getElementById('findings-list').innerHTML =
+      findings.map(function(f,i){ return renderFinding(f,i); }).join('');
+  }
+
+  function renderDownloads(d) {
+    var el = document.getElementById('downloads-section');
+    var btns = [];
+    var icon = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>';
+    if (d.vex_path) {
+      btns.push('<a class="download-btn" href="../'+esc(d.vex_path)+'">'+icon+' vex.json</a>');
+    }
+    d.findings.forEach(function(f){
+      (f.drafts||[]).forEach(function(p){
+        var name = p.split('/').pop();
+        btns.push('<a class="download-btn" href="../'+esc(p)+'">'+icon+' '+esc(name)+'</a>');
+      });
+    });
+    el.innerHTML = '<span class="downloads-label">Downloads</span>'+btns.join('');
+  }
+
+  function renderCoverage(coverage) {
+    if (!coverage) return;
+    var note = document.getElementById('footer-note');
+    var span = document.createElement('div');
+    span.style.cssText = 'margin-top:6px;font-size:11px;color:var(--muted);font-family:var(--font-mono)';
+    span.textContent = 'Coverage: '+coverage.files_parsed+' / '+coverage.files_found+' files parsed';
+    note.appendChild(span);
+  }
+
+  function setupAnimations() {
+    if (!window.IntersectionObserver) {
+      document.querySelectorAll('.finding-card,.hop').forEach(function(el){ el.classList.add('visible'); });
+      return;
+    }
+    var io = new IntersectionObserver(function(entries){
+      entries.forEach(function(e){
+        if (e.isIntersecting) {
+          e.target.classList.add('visible');
+          var hops = e.target.querySelectorAll('.hop');
+          hops.forEach(function(hop, i){
+            setTimeout(function(){ hop.classList.add('visible'); }, 120 + i*100);
+          });
+          io.unobserve(e.target);
+        }
+      });
+    }, {threshold:0.05});
+    document.querySelectorAll('.finding-card').forEach(function(c){ io.observe(c); });
+  }
+
+  loadData().then(function(d){
+    renderHeader(d);
+    renderClock(d.clock);
+    renderSummary(d.summary);
+    renderFindings(d.findings);
+    renderDownloads(d);
+    renderCoverage(d.coverage);
+    requestAnimationFrame(function(){ setupAnimations(); });
+  });
+
+})();
+</script>
+</body>
+</html>

